int validate_utf8(const uint8_t* data, size_t len) {
    size_t i = 0;
    while (i < len) {
        uint8_t b = data[i];
        int expected = kUtf8LenTable[b];
        if (expected == 0) return (int)i;
        if (i + expected > len) return (int)i;

        // Validate continuation bytes
        for (int j = 1; j < expected; j++) {
            if ((data[i + j] & 0xC0) != 0x80) return (int)i;
        }

        // Decode codepoint and check for overlong encodings
        uint32_t cp = 0;
        if (expected == 1) {
            cp = b;
        } else if (expected == 2) {
            cp = ((uint32_t)(b & 0x1F) << 6) | (data[i+1] & 0x3F);
            if (cp < 0x80) return (int)i;
        } else if (expected == 3) {
            cp = ((uint32_t)(b & 0x0F) << 12) |
                 ((uint32_t)(data[i+1] & 0x3F) << 6) |
                 (data[i+2] & 0x3F);
            if (cp < 0x800) return (int)i;
            // Reject surrogates
            if (cp >= 0xD800 && cp <= 0xDFFF) return (int)i;
        } else if (expected == 4) {
            cp = ((uint32_t)(b & 0x07) << 18) |
                 ((uint32_t)(data[i+1] & 0x3F) << 12) |
                 ((uint32_t)(data[i+2] & 0x3F) << 6) |
                 (data[i+3] & 0x3F);
            if (cp < 0x10000 || cp > 0x10FFFF) return (int)i;
        }

        i += expected;
    }
    return -1;  // valid
}

bool iequal_ascii(const char* a, size_t a_len, const char* b, size_t b_len) {
    if (a_len != b_len) return false;
    for (size_t i = 0; i < a_len; i++) {
        if (kSimpleFold[(uint8_t)a[i]] != kSimpleFold[(uint8_t)b[i]])
            return false;
    }
    return true;
}

